DG.put("ath-pakhyaan-charitr-likhyate/264",{"n":264,"title":null,"title_roman":null,"page":2063,"blocks":[{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2063,"meaning_status":"draft"},{"type":"verse","number":[1],"number_text":"੧।","page":2063,"lines":[{"gurmukhi":"ਨ੍ਰਿਪਤਿ ਬਿਚਛਨ ਸੈਨ ਕੇ ਮਤੀ ਸੁਲਛਨਿ ਨਾਰਿ।","roman":"Nripti bichchhan sain ke matee sulachhni naari |","meaning_en":"Bichachhan Sen was a king, and Sulachhani was his queen;","page":2063,"meaning_status":"draft","note":"ਨ੍ਰਿਪਤਿ ਬਿਚਛਨ ਸੈਨ ਕੇ ਮਤੀ ਸੁਲਛਨਿ ਨਾਰਿ: read as 'Bichachhan Sen the king, and his wife Sulachhan Mati'; the names are uncertain, 'bichachhan' and 'sulachhani' also mean 'clever' and 'well-featured'."},{"gurmukhi":"ਦਛਨਿ ਕੋ ਰਾਜਾ ਰਹੈ ਧਨ ਕਰਿ ਭਰੇ ਭੰਡਾਰ। ੧।","roman":"Dachhni ko raajaa rahai dhan kari bhare bhandaar | 1 |","meaning_en":"he was king of the south, with his treasuries full of wealth.","page":2063,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2063,"meaning_status":"draft"},{"type":"verse","number":[2],"number_text":"੨।","page":2063,"lines":[{"gurmukhi":"ਬਿਰਹ ਕੁਅਰਿ ਤਾ ਕੇ ਦੁਹਿਤਾ ਇਕ। ਪੜੀ ਬ੍ਯਾਕਰਨ ਕੋਕ ਸਾਸਤ੍ਰ ਨਿਕ।","roman":"Birah kuari taa ke duhitaa ik | paree byaakran kok saasatr nik |","meaning_en":"Birah Kuari was his daughter, well versed in grammar and the Koka Shastra.","page":2063,"meaning_status":"draft","note":"ਕੋਕ ਸਾਸਤ੍ਰ: the Koka treatise on love."},{"gurmukhi":"ਨਾਨਾ ਬਿਧਿ ਕੀ ਬਿਦ੍ਯਾ ਧਰੈ। ਬਹੁ ਪੰਡਿਤ ਉਸਤਿਤ ਜਿਹ ਕਰੈ। ੨।","roman":"Naanaa bidhi kee bidyaa dharai | bahu pandit ustit jih karai | 2 |","meaning_en":"She held many kinds of learning, and many pandits praised her.","page":2063,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2063,"meaning_status":"draft"},{"type":"verse","number":[3],"number_text":"੩।","page":2063,"lines":[{"gurmukhi":"ਅਧਿਕ ਰੂਪ ਤਿਹ ਕੁਅਰਿ ਕੋ ਬ੍ਰਹਮ ਬਨਾਯੋ ਆਪੁ।","roman":"Adhik roop tih kuari ko braham banaayo aapu |","meaning_en":"Brahma himself had made the princess of surpassing beauty;","page":2063,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਸਮ ਸੁੰਦਰਿ ਥਾਪਿ ਕਰਿ ਸਕਾ ਨ ਦੂਸਰਿ ਥਾਪੁ। ੩।","roman":"Taa sam sundri thaapi kari sakaa na doosri thaapu | 3 |","meaning_en":"having made her, he could not make another beauty like her.","page":2063,"meaning_status":"draft"}]},{"type":"verse","number":[4],"number_text":"੪।","page":2063,"lines":[{"gurmukhi":"ਪਰੀ ਪਦਮਨੀ ਪੰਨਗੀ ਤਾ ਸਮ ਔਰ ਨ ਕੋਇ।","roman":"Paree padamnee panngee taa sam aur na koi |","meaning_en":"Fairy, Padmini, serpent-woman, none was like her;","page":2063,"meaning_status":"draft"},{"gurmukhi":"ਨਰੀ ਨ੍ਰਿਤਕਾਰੀ ਨਟੀ ਦੁਤਿਯ ਨ ਵੈਸੀ ਹੋਇ। ੪।","roman":"Naree nritkaaree natee dutiy na vaisee hoi | 4 |","meaning_en":"a human woman, a dancer, an actress, none was a second like her.","page":2063,"meaning_status":"draft"}]},{"type":"verse","number":[5],"number_text":"੫।","page":2063,"lines":[{"gurmukhi":"ਹਿੰਦੁਨਿ ਤੁਰਕਾਨੀ ਜਿਤੀ ਸੁਰੀ ਆਸੁਰੀ ਬਾਰਿ।","roman":"Hinduni turkaanee jitee suree aasuree baari |","meaning_en":"Of all Hindu and Turkish women, goddesses and demonesses,","page":2063,"meaning_status":"draft","note":"ਹਿੰਦੁਨਿ ਤੁਰਕਾਨੀ: Hindu women and Turkish (Muslim) women; printed so. ਬਾਰਿ: read as 'all'; uncertain."},{"gurmukhi":"ਖੋਜਤ ਜਗਤ ਨ ਪਾਇਯਤ ਦੂਸਰ ਵੈਸੀ ਨਾਰਿ। ੫।","roman":"Khojat jagat na paaiyat doosar vaisee naari | 5 |","meaning_en":"searching the world no second woman like her is found.","page":2063,"meaning_status":"draft"}]},{"type":"verse","number":[6],"number_text":"੬।","page":2063,"lines":[{"gurmukhi":"ਇੰਦ੍ਰ ਲੋਕ ਕੀ ਅਪਛਰਾ ਤਾਹਿ ਬਿਲੋਕਨਿ ਜਾਤ।","roman":"Indr lok kee apachhraa taahi bilokni jaat |","meaning_en":"Apsaras of Indra's world went to look at her;","page":2063,"meaning_status":"draft"},{"gurmukhi":"ਨਿਰਖਤ ਰੂਪ ਅਘਾਤ ਨਹਿ ਪਲਕ ਨ ਭੂਲਿ ਲਗਾਤ। ੬।","roman":"Nirkhat roop aghaat nahi palak na bhooli lagaat | 6 |","meaning_en":"seeing her beauty they were not sated, and did not blink even by mistake.","page":2063,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2063,"meaning_status":"draft"},{"type":"verse","number":[7],"number_text":"੭।","page":2063,"lines":[{"gurmukhi":"ਹੇਰਿ ਅਪਛਰਾ ਤਿਹ ਮੁਸਕਾਨੀ। ਸਖਿਨ ਮਾਝ ਇਹ ਭਾਤਿ ਬਖਾਨੀ।","roman":"Heri apachhraa tih muskaanee | sakhin maajh ih bhaati bakhaanee |","meaning_en":"Seeing her, an Apsara smiled and said among her friends:","page":2063,"meaning_status":"draft"},{"gurmukhi":"ਜੈਸੀ ਯਹ ਸੁੰਦਰ ਜਗਿ ਮਾਹੀ। ਐਸੀ ਅਵਰ ਕੁਅਰਿ ਕਹੂੰ ਨਾਹੀ। ੭।","roman":"Jaisee yah sundar jagi maahee | aisee avar kuari kahoon naahee | 7 |","meaning_en":"\"As beautiful as this one is in the world, no other princess is like her.\"","page":2063,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਸ਼ਾਹ ਪਰੀ ਵਾਚ","gurmukhi":"ਸ਼ਾਹ ਪਰੀ ਵਾਚ","roman":"Shaah paree vaach","meaning_en":"Shah Pari said:","page":2063,"meaning_status":"draft","note":"ਸ਼ਾਹ ਪਰੀ: 'the king of the fairies' or 'queen fairy'; the name Shah Pari used here for the fairy; later also called Sardar Pari."},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2063,"meaning_status":"draft"},{"type":"verse","number":[8],"number_text":"੮।","page":2063,"lines":[{"gurmukhi":"ਜੈਸੀ ਯਹ ਸੁੰਦਰੀ ਨ ਸੁੰਦਰਿ ਕਹੂੰ ਜਗ।","roman":"Jaisee yah sundree na sundri kahoon jag |","meaning_en":"\"No beauty in the world is such as this beauty is;","page":2063,"meaning_status":"draft"},{"gurmukhi":"ਥਕਤਿ ਰਹਤ ਜਿਹ ਰੂਪ ਚਰਾਚਰ ਹੇਰਿ ਮਗ।","roman":"Thakti rahat jih roop charaachar heri mag |","meaning_en":"all creatures, moving and still, stop and look at her path, as if tired,","page":2063,"meaning_status":"draft"},{"gurmukhi":"ਯਾ ਸਮ ਰੂਪ ਕੁਅਰ ਜੋ ਕਤਹੂੰ ਪਾਈਐ।","roman":"Yaa sam roop kuar jo kathoon paaeeai |","meaning_en":"if a prince like her in beauty can be found anywhere,","page":2063,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਰਿ ਕੈ ਕ੍ਰੋਰਿ ਉਪਾਇ ਸੁ ਯਾਹਿ ਰਿਝਾਇਐ। ੮।","roman":"Ho kari kai krori upaai su yaahi rijhaaiai | 8 |","meaning_en":"then by ten million means she should be won for him.\"","page":2063,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2063,"meaning_status":"draft"},{"type":"verse","number":[9],"number_text":"੯।","page":2063,"lines":[{"gurmukhi":"ਪਰੀ ਸੁਨਤ ਐਸੇ ਬਚਨ ਸਭਨ ਕਹਾ ਸਿਰ ਨ੍ਯਾਇ।","roman":"Paree sunat aise bachan sabhan kahaa sir nyaai |","meaning_en":"Hearing such words the fairies all bowed their heads and said,","page":2063,"meaning_status":"draft"},{"gurmukhi":"ਯਾ ਸਮ ਸੁੰਦਰ ਪੁਰਖ ਇਹ ਦੈ ਹੈ ਖੋਜਿ ਮਿਲਾਇ। ੯।","roman":"Yaa sam sundar purakh ih dai hai khoji milaai | 9 |","meaning_en":"\"We will search out a handsome man like her and unite them.\"","page":2063,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2065,"meaning_status":"draft"},{"type":"verse","number":[10],"number_text":"੧੦।","page":2065,"lines":[{"gurmukhi":"ਪਰੀ ਰਾਜ ਕੀ ਪਰੀ ਸਭਾਗ੍ਯਾ ਪਾਇ ਕੈ।","roman":"Paree raaj kee paree sabhaagyaa paai kai |","meaning_en":"The fairy queen of the fairies, receiving the order, set out","page":2065,"meaning_status":"draft","note":"ਸਭਾਗ੍ਯਾ: read as 'by good fortune/with approval'; uncertain."},{"gurmukhi":"ਚਲਤ ਭਈ ਸਖਿ ਸਹਸ ਸਿੰਗਾਰ ਬਨਾਇ ਕੈ।","roman":"Chalat bhaee sakhi sahas singaar banaai kai |","meaning_en":"with a thousand friends, adorned.","page":2065,"meaning_status":"draft"},{"gurmukhi":"ਖੋਜਿ ਫਿਰੀ ਸਭ ਦੇਸ ਨ ਸੁੰਦਰ ਪਾਇਯੋ।","roman":"Khoji phiree sabh des na sundar paaiyo |","meaning_en":"She searched through all countries and found no handsome man;","page":2065,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਏਕ ਹੁਤੋ ਰਿਖਿ ਤਿਹ ਤਿਨ ਭੇਦ ਬਤਾਇਯੋ। ੧੦।","roman":"Ho ek huto rikhi tih tin bhed bataaiyo | 10 |","meaning_en":"there was one sage there, who told her the secret.","page":2065,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2065,"meaning_status":"draft"},{"type":"verse","number":[11],"number_text":"੧੧।","page":2065,"lines":[{"gurmukhi":"ਇਕ ਰਿਖਿ ਥੋ ਕਾਨਨ ਇਕ ਭੀਤਰ। ਤਾ ਸਮ ਤਪੀ ਨ ਥੋ ਅਵਨੀ ਪਰ।","roman":"Ik rikhi tho kaanan ik bheetar | taa sam tapee na tho avnee par |","meaning_en":"There was a sage in a certain forest; none on earth was as ascetic as he.","page":2065,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨਿਕ ਅਪਛਰਾ ਤਹਾ ਨਿਹਾਰੀ। ਕ੍ਰਿਪਾ ਜਾਨਿ ਇਹ ਭਾਤਿ ਉਚਾਰੀ। ੧੧।","roman":"Tinik apachhraa tahaa nihaaree | kripaa jaani ih bhaati uchaaree | 11 |","meaning_en":"He saw the Apsara there, and, from kindness, spoke thus:","page":2065,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2065,"meaning_status":"draft"},{"type":"verse","number":[12],"number_text":"੧੨।","page":2065,"lines":[{"gurmukhi":"ਕੋ ਹੈ ਰੀ ਤੂ ਕਹ ਚਲੀ ਕ੍ਯੋ ਆਈ ਇਹ ਦੇਸ।","roman":"Ko hai ree too kah chalee kyo aaee ih des |","meaning_en":"\"Who are you, where are you going, why have you come to this country?","page":2065,"meaning_status":"draft"},{"gurmukhi":"ਕੈ ਤੂ ਇਸਤ੍ਰੀ ਇੰਦ੍ਰ ਕੀ ਕੈ ਅਬਲਾ ਅਲਿਕੇਸ। ੧੨।","roman":"Kai too istree indr kee kai ablaa alikes | 12 |","meaning_en":"Are you Indra's wife, or the wife of Kubera?\"","page":2065,"meaning_status":"draft","note":"ਅਲਿਕੇਸ: Kubera."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2065,"meaning_status":"draft"},{"type":"verse","number":[13],"number_text":"੧੩।","page":2065,"lines":[{"gurmukhi":"ਕਿਹ ਕਾਰਨ ਤੇ ਤੈ ਹ੍ਯਾ ਆਈ। ਕਹੁ ਕਵਨੈ ਕਿਹ ਕਾਜ ਪਠਾਈ।","roman":"Kih kaaran te tai hyaa aaee | kahu kavnai kih kaaj pathaaee |","meaning_en":"\"For what reason have you come here? Say who sent you and for what purpose.","page":2065,"meaning_status":"draft"},{"gurmukhi":"ਸਾਚ ਕਹੇ ਬਿਨੁ ਜਾਨ ਨ ਦੈ ਹੌ। ਨਾਤਰ ਸ੍ਰਾਪ ਅਬੈ ਤੁਹਿ ਕੈ ਹੌ। ੧੩।","roman":"Saach kahe binu jaan na dai hau | naatar sraap abai tuhi kai hau | 13 |","meaning_en":"I will not let you go without the truth; otherwise I will curse you now.\"","page":2065,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2065,"meaning_status":"draft"},{"type":"verse","number":[14],"number_text":"੧੪।","page":2065,"lines":[{"gurmukhi":"ਏਕ ਦਿਵਸ ਮੁਨਿ ਚਲੀ ਅਪਛਰਾ ਧਾਇ ਕੈ।","roman":"Ek divas muni chalee apachhraa dhaai kai |","meaning_en":"\"One day, sage, the Apsara went running;","page":2065,"meaning_status":"draft","note":"Speaker is the fairy telling the sage her story; unmarked."},{"gurmukhi":"ਨਿਰਖਿ ਕੁਅਰਿ ਕੋ ਰੂਪ ਰਹੀ ਉਰਝਾਇ ਕੈ।","roman":"Nirkhi kuari ko roop rahee urjhaai kai |","meaning_en":"seeing the princess's beauty she was entangled,","page":2065,"meaning_status":"draft"},{"gurmukhi":"ਚਿਤ ਮਹਿ ਕਿਯਾ ਬਿਚਾਰ ਕੁਅਰ ਹੂੰ ਪਾਇਯੈ।","roman":"Chit mahi kiyaa bichaar kuar hoon paaiyai |","meaning_en":"and thought in her mind, 'I should find a prince,","page":2065,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਐਸੋ ਸੁੰਦਰ ਖੋਜਿ ਸੁ ਯਾਹਿ ਮਿਲਾਇਯੈ। ੧੪।","roman":"Ho aiso sundar khoji su yaahi milaaiyai | 14 |","meaning_en":"search out such a handsome one and unite him with her.'","page":2065,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2065,"meaning_status":"draft"},{"type":"verse","number":[15],"number_text":"੧੫।","page":2065,"lines":[{"gurmukhi":"ਹਮ ਸੀ ਸਖੀ ਸਹਸ੍ਰਨ ਸੁੰਦਰਿ। ਪਠੈ ਦਈ ਦਸਹੂੰ ਦਿਸਿ ਮੁਨਿ ਬਰ।","roman":"Ham see sakhee sahsran sundri | pathai daee dashoon disi muni bar |","meaning_en":"\"The excellent sage sent thousands of beautiful friends like me in all ten directions.","page":2065,"meaning_status":"draft","note":"Read as the fairy queen's account of her mission; the 'sage' here printed so; uncertain."},{"gurmukhi":"ਖੋਜਿ ਥਕੀ ਪ੍ਰੀਤਮ ਨਹਿ ਪਾਯੋ। ਦੇਸ ਦੇਸ ਸਭ ਹੇਰਿ ਗਵਾਯੋ। ੧੫।","roman":"Khoji thakee preetam nahi paayo | des des sabh heri gavaayo | 15 |","meaning_en":"I searched until weary and have not found a lover; I wasted time looking over all the countries.\"","page":2065,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2065,"meaning_status":"draft"},{"type":"verse","number":[16],"number_text":"੧੬।","page":2065,"lines":[{"gurmukhi":"ਖੋਜਿ ਦੇਸ ਬ੍ਯਾਕੁਲ ਭਈ ਆਈ ਤੁਮਰੇ ਪਾਸ।","roman":"Khoji des byaakul bhaee aaee tumre paas |","meaning_en":"\"Having searched the countries I became distressed and have come to you;","page":2065,"meaning_status":"draft"},{"gurmukhi":"ਦੀਜੈ ਸੁਘਰ ਬਤਾਇ ਕਹੂੰ ਕਾਰਜ ਆਵਹਿ ਰਾਸ। ੧੬।","roman":"Deejai sughar bataai kahoon kaaraj aavhi raas | 16 |","meaning_en":"tell me of a clever one anywhere so that my work may succeed.\"","page":2065,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2065,"meaning_status":"draft"},{"type":"verse","number":[17],"number_text":"੧੭।","page":2065,"lines":[{"gurmukhi":"ਬ੍ਰਹਮਾ ਏਕ ਪੁਰਖ ਉਪਜਾਯੋ। ਨ੍ਰਿਪ ਕੇ ਧਾਮ ਜਨਮ ਤਿਨ ਪਾਯੋ।","roman":"Brahmaa ek purakh upjaayo | nrip ke dhaam janam tin paayo |","meaning_en":"\"Brahma created one man; he took birth in a king's house.","page":2065,"meaning_status":"draft","note":"Speaker is the sage."},{"gurmukhi":"ਸਾਤ ਸਮੁੰਦ੍ਰਨ ਪਾਰ ਬਸਤ ਸੋ। ਕੋ ਪਹੁਚੈ ਤਿਹ ਲ੍ਯਾਇ ਸਕਤ ਸੋ। ੧੭।","roman":"Saat samundran paar basat so | ko pahuchai tih lyaai sakat so | 17 |","meaning_en":"He lives beyond the seven seas; who can reach there and bring him?\"","page":2065,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2067,"meaning_status":"draft"},{"type":"verse","number":[18],"number_text":"੧੮।","page":2067,"lines":[{"gurmukhi":"ਰਿਖਿ ਕੇ ਇਹ ਬਿਧਿ ਬਚਨ ਸੁਨਿ ਚਲਤ ਭਈ ਸੁ ਕੁਮਾਰਿ।","roman":"Rikhi ke ih bidhi bachan suni chalat bhaee su kumaari |","meaning_en":"Hearing the sage's words, the fairy girl set out;","page":2067,"meaning_status":"draft"},{"gurmukhi":"ਸਪਤ ਸਿੰਧ ਕੇ ਛਿਨਿਕ ਮਹਿ ਜਾਤ ਭਈ ਉਹਿ ਪਾਰ। ੧੮।","roman":"Sapat sindh ke chhinik mahi jaat bhaee uhi paar | 18 |","meaning_en":"in a moment she went across the seven seas to the other side.","page":2067,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2067,"meaning_status":"draft"},{"type":"verse","number":[19],"number_text":"੧੯।","page":2067,"lines":[{"gurmukhi":"ਸੁੰਦਰ ਸਦਨ ਹੁਤੋ ਜਹ ਨ੍ਰਿਪ ਬਰ। ਜਾਤ ਭਈ ਸੁੰਦਰਿ ਤਾਹਿ ਘਰ।","roman":"Sundar sadan huto jah nrip bar | jaat bhaee sundri taahi ghar |","meaning_en":"Where there was the fine king's beautiful house, the beautiful woman went to that house;","page":2067,"meaning_status":"draft"},{"gurmukhi":"ਜਹ ਨ੍ਰਿਪ ਸੁਤ ਆਸ੍ਰਮ ਸੁਨਿ ਲੀਯਾ। ਗਈ ਤਹਾ ਤਿਨ ਬਿਲਮ ਨ ਕੀਯਾ। ੧੯।","roman":"Jah nrip sut aasram suni leeyaa | gaee tahaa tin bilam na keeyaa | 19 |","meaning_en":"where she had heard the prince's hermitage was, she went there without delay.","page":2067,"meaning_status":"draft","note":"ਆਸ੍ਰਮ: 'dwelling/abode'; read so."}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":2067,"lines":[{"gurmukhi":"ਲੋਕੰਜਨ ਡਾਰਤ ਚਖ ਭਈ। ਪਰਗਟ ਹੁਤੀ ਲੋਪ ਹ੍ਵੈ ਗਈ।","roman":"Lokanjan daarat chakh bhaee | pargat hutee lop hvai gaee |","meaning_en":"She put lokanjan (eye-salve of invisibility) in her eyes; she was visible and vanished.","page":2067,"meaning_status":"draft","note":"ਲੋਕੰਜਨ: a magical eye-salve; read as making her invisible; uncertain."},{"gurmukhi":"ਯਹ ਸਭ ਹੀ ਕੋ ਰੂਪ ਨਿਹਾਰੈ। ਯਾ ਕੌ ਕੋਊ ਨ ਪੁਰਖ ਬਿਚਾਰੈ। ੨੦।","roman":"Yah sabh hee ko roop nihaarai | yaa kau ko'oo na purakh bichaarai | 20 |","meaning_en":"She could see everyone's form, but none of the men could see her.","page":2067,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2067,"meaning_status":"draft"},{"type":"verse","number":[21],"number_text":"੨੧।","page":2067,"lines":[{"gurmukhi":"ਸਿੰਘ ਦਿਲੀਸ ਧਾਰਿ ਬਸਤ੍ਰ ਬੈਠੇ ਜਹਾ।","roman":"Singh dilees dhaari basatr baithe jahaa |","meaning_en":"Where Singh Dilis (Dilip Singh) sat, adorned in fine clothes,","page":2067,"meaning_status":"draft","note":"ਸਿੰਘ ਦਿਲੀਸ: 'Singh Dilis' printed so; read as the prince's name, Dilip Singh; the text later uses ਦਿਲੀਪ ਸਿੰਘ."},{"gurmukhi":"ਲੋਕੰਜਨ ਦ੍ਰਿਗ ਡਾਰਿ ਜਾਤ ਭੀ ਤ੍ਰਿਯ ਤਹਾ।","roman":"Lokanjan drig daari jaat bhee triy tahaa |","meaning_en":"the woman went there, having put the salve in her eyes.","page":2067,"meaning_status":"draft"},{"gurmukhi":"ਹੇਰਿ ਤਵਨ ਕੀ ਪ੍ਰਭਾ ਰਹੀ ਉਰਝਾਇ ਕਰਿ।","roman":"Heri tavan kee prabhaa rahee urjhaai kari |","meaning_en":"Seeing his radiance she was entangled,","page":2067,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੁਧਿ ਯਾ ਕੀ ਗੀ ਭੂਲਿ ਰਹੀ ਲਲਚਾਇ ਕਰਿ। ੨੧।","roman":"Ho sudhi yaa kee gee bhooli rahee lalchaai kari | 21 |","meaning_en":"her senses left her and she remained lost in longing.","page":2067,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2067,"meaning_status":"draft"},{"type":"verse","number":[22],"number_text":"੨੨।","page":2067,"lines":[{"gurmukhi":"ਯਹ ਸੁਧਿ ਤਾਹਿ ਬਿਸਰਿ ਕਰਿ ਗਈ। ਤਿਹ ਪੁਰ ਬਸਤ ਬਰਖ ਬਹੁ ਭਈ।","roman":"Yah sudhi taahi bisri kari gaee | tih pur basat barakh bahu bhaee |","meaning_en":"She forgot this errand; she lived in that city for many years.","page":2067,"meaning_status":"draft"},{"gurmukhi":"ਕਿਤਕ ਦਿਨਨ ਵਾ ਕੀ ਸੁਧਿ ਆਈ। ਮਨ ਮਹਿ ਤਰੁਨੀ ਅਧਿਕ ਲਜਾਈ। ੨੨।","roman":"Kitak dinan vaa kee sudhi aaee | man mahi tarunee adhik lajaaee | 22 |","meaning_en":"After some days she remembered it, and the young woman felt much shame in her mind.","page":2067,"meaning_status":"draft","note":"ਵਾ ਕੀ ਸੁਧਿ: 'memory of her (the princess)'."}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":2067,"lines":[{"gurmukhi":"ਜੌ ਯਹ ਬਾਤ ਪਰੀ ਸੁਨਿ ਪੈ ਹੈ। ਮੋ ਕਹ ਕਾਢਿ ਸ੍ਵਰਗ ਤੇ ਦੈ ਹੈ।","roman":"Jau yah baat paree suni pai hai | mo kah kaadhi svarag te dai hai |","meaning_en":"\"If this affair is heard of, they will throw me out of heaven;","page":2067,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਤੇ ਯਾ ਕੌ ਕਰੌ ਉਪਾਈ। ਜਾ ਤੇ ਇਹ ਉਹਿ ਦੇਉ ਮਿਲਾਈ। ੨੩।","roman":"Taa te yaa kau karau upaaee | jaa te ih uhi deu milaaee | 23 |","meaning_en":"so I will make a plan by which I may unite him with her.\"","page":2067,"meaning_status":"draft"}]},{"type":"verse","number":[24],"number_text":"੨੪।","page":2067,"lines":[{"gurmukhi":"ਆਲਯ ਹੁਤੋ ਕੁਅਰ ਕੋ ਜਹਾ। ਵਾ ਕੋ ਚਿਤ੍ਰ ਲਿਖਤ ਭਈ ਤਹਾ।","roman":"Aalay huto kuar ko jahaa | vaa ko chitr likhat bhaee tahaa |","meaning_en":"Where the prince's dwelling was, she drew a picture of the princess there.","page":2067,"meaning_status":"draft","note":"ਚਿਤ੍ਰ: picture/portrait; ਵਾ ਕੋ ਚਿਤ੍ਰ: 'a portrait of her', the princess."},{"gurmukhi":"ਚਿਤ੍ਰ ਜਬੈ ਤਿਨ ਕੁਅਰ ਨਿਹਾਰਾ। ਰਾਜ ਪਾਟ ਸਭ ਹੀ ਤਜਿ ਡਾਰਾ। ੨੪।","roman":"Chitr jabai tin kuar nihaaraa | raaj paat sabh hee taji daaraa | 24 |","meaning_en":"When the prince saw the picture, he cast aside his whole kingdom and throne.","page":2067,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2067,"meaning_status":"draft"},{"type":"verse","number":[25],"number_text":"੨੫।","page":2067,"lines":[{"gurmukhi":"ਮਨ ਮੈ ਭਯੋ ਉਦਾਸ ਰਾਜ ਕੋ ਤ੍ਯਾਗਿ ਕੈ।","roman":"Man mai bhayo udaas raaj ko tyaagi kai |","meaning_en":"He became dejected in mind and gave up the kingdom;","page":2067,"meaning_status":"draft"},{"gurmukhi":"ਰੈਨਿ ਦਿਵਸ ਤਹ ਬੈਠਿ ਰਹਤ ਅਨੁਰਾਗਿ ਕੈ।","roman":"Raini divas tah baithi rahat anuraagi kai |","meaning_en":"night and day he sat there in love,","page":2067,"meaning_status":"draft"},{"gurmukhi":"ਰੋਇ ਰੋਇ ਦ੍ਰਿਗ ਨੈਨਨ ਰੁਹਰ ਬਹਾਵਈ।","roman":"Roi roi drig nainan ruhar bahaavaee |","meaning_en":"weeping and weeping, he shed tears from his eyes,","page":2067,"meaning_status":"draft","note":"ਰੁਹਰ: read as 'tears' (a river of tears); uncertain."},{"gurmukhi":"ਹੋ ਕੋਟਿਨ ਕਰੈ ਬਿਚਾਰ ਨ ਤਾ ਕੌ ਪਾਵਈ। ੨੫।","roman":"Ho kotin karai bichaar na taa kau paavaee | 25 |","meaning_en":"and thought in ten million ways, but could not find her.","page":2067,"meaning_status":"draft"}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":2067,"lines":[{"gurmukhi":"ਨਟੀ ਨਾਟਕੀ ਨ੍ਰਿਪਨੀ ਨ੍ਰਿਤਣਿ ਬਖਾਨਿਯੈ।","roman":"Natee naatkee nripnee nritni bakhaaniyai |","meaning_en":"Is she an actress, a player, a queen, a dancer?","page":2067,"meaning_status":"draft"},{"gurmukhi":"ਨਰੀ ਨਾਗਨੀ ਨਗਨੀ ਨਿਜੁ ਤ੍ਰਿਯ ਜਾਨਿਯੈ।","roman":"Naree naagnee nagnee niju triy jaaniyai |","meaning_en":"A human woman, a snake-woman, a mountain-woman, or his own woman, what should one take her for?","page":2067,"meaning_status":"draft","note":"ਨਿਜੁ ਤ੍ਰਿਯ: 'his own woman'; read as printed."},{"gurmukhi":"ਸਿਵੀ ਬਾਸਵੀ ਸਸੀ ਕਿ ਰਵਿ ਤਨ ਜਈ।","roman":"Sivee baasvee sasee ki ravi tan jaee |","meaning_en":"Born of Shiva's consort, Indrani, the moon, or the sun?","page":2067,"meaning_status":"draft","note":"ਸਿਵੀ: Shivi, Parvati; read as a list of possible beings; uncertain."},{"gurmukhi":"ਹੋ ਚੇਟਕ ਚਿਤ੍ਰ ਦਿਖਾਇ ਚਤੁਰਿ ਚਿਤ ਲੈ ਗਈ। ੨੬।","roman":"Ho chetak chitr dikhaai chaturi chit lai gaee | 26 |","meaning_en":"A clever one has shown a picture as a trick and taken his heart.","page":2067,"meaning_status":"draft","note":"ਚੇਟਕ: 'magic, spell, trick'."}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":2069,"lines":[{"gurmukhi":"ਲਿਖ੍ਯੋ ਚਿਤ੍ਰ ਇਹ ਠੌਰ ਬਹੁਰਿ ਤਿਹ ਠਾ ਗਈ।","roman":"Likhyo chitr ih thaur bahuri tih thaa gaee |","meaning_en":"The picture was drawn in this place, then she went to that other place;","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਚਿਤ੍ਰ ਚਤੁਰਿ ਕੇ ਭਵਨ ਬਿਖੈ ਲਿਖਤੀ ਭਈ।","roman":"Chitr chaturi ke bhavan bikhai likhtee bhaee |","meaning_en":"she drew the picture in the clever woman's (princess's) house.","page":2069,"meaning_status":"draft","note":"ਚਤੁਰਿ ਕੇ ਭਵਨ: 'in the clever woman's house'; read as the princess's house; uncertain."},{"gurmukhi":"ਪ੍ਰਾਤ ਕੁਅਰਿ ਕੋ ਜਬ ਤਿਨ ਚਿਤ੍ਰ ਨਿਹਾਰਿਯੋ।","roman":"Praat kuari ko jab tin chitr nihaariyo |","meaning_en":"In the morning, when the princess saw the picture,","page":2069,"meaning_status":"draft","note":"Read as the picture of the prince; the princess is the one who sees it."},{"gurmukhi":"ਹੋ ਰਾਜ ਪਾਟ ਸਭ ਸਾਜ ਤਬੈ ਤਜਿ ਡਾਰਿਯੋ। ੨੭।","roman":"Ho raaj paat sabh saaj tabai taji daariyo | 27 |","meaning_en":"she then threw away all her royal throne and trappings.","page":2069,"meaning_status":"draft"}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":2069,"lines":[{"gurmukhi":"ਨਿਰਖਿ ਕੁਅਰ ਕੋ ਚਿਤ੍ਰ ਕੁਅਰਿ ਅਟਕਤ ਭਈ।","roman":"Nirkhi kuar ko chitr kuari atkat bhaee |","meaning_en":"Seeing the prince's picture, the princess was held fast;","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜ ਪਾਟ ਧਨ ਕੀ ਸੁਧਿ ਸਭ ਜਿਯ ਤੇ ਗਈ।","roman":"Raaj paat dhan kee sudhi sabh jiy te gaee |","meaning_en":"all awareness of kingdom, throne and wealth left her heart.","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਬਢੀ ਪ੍ਰੇਮ ਕੀ ਪੀਰ ਬਤਾਵੈ ਕਹੋ ਕਿਹ।","roman":"Badhee prem kee peer bataavai kaho kih |","meaning_en":"The pain of love grew; to whom could she tell it,","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜੋ ਤਿਹ ਸੋਕ ਨਿਵਾਰਿ ਮਿਲਾਵੈ ਆਨਿ ਤਿਹ। ੨੮।","roman":"Ho jo tih sok nivaari milaavai aani tih | 28 |","meaning_en":"who would remove her sorrow and bring him to her?","page":2069,"meaning_status":"draft"}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":2069,"lines":[{"gurmukhi":"ਮਤਵਾਰੇ ਕੀ ਭਾਤਿ ਕੁਅਰਿ ਬਵਰੀ ਭਈ।","roman":"Matvaare kee bhaati kuari bavree bhaee |","meaning_en":"The princess became mad like a drunkard;","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਖਾਨ ਪਾਨ ਕੀ ਸੁਧਿ ਤਬ ਹੀ ਤਜਿ ਕਰਿ ਦਈ।","roman":"Khaan paan kee sudhi tab hee taji kari daee |","meaning_en":"she gave up caring for food and drink.","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਹਸਿ ਹਸਿ ਕਬਹੂੰ ਉਠੈ ਕਬੈ ਗੁਨ ਗਾਵਈ।","roman":"Hasi hasi kabhoon uthai kabai gun gaavaee |","meaning_en":"Sometimes she rose laughing and laughing, sometimes she sang his praises,","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਬਹੂੰ ਰੋਵਤ ਦਿਨ ਅਰੁ ਰੈਨਿ ਬਿਤਾਵਈ। ੨੯।","roman":"Ho kabhoon rovat din aru raini bitaavaee | 29 |","meaning_en":"sometimes she wept, passing day and night.","page":2069,"meaning_status":"draft"}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":2069,"lines":[{"gurmukhi":"ਦਿਨ ਦਿਨ ਪਿਯਰੀ ਹੋਤ ਕੁਅਰਿ ਤਨ ਜਾਵਈ।","roman":"Din din piyree hot kuari tan jaavaee |","meaning_en":"Day by day the princess's body grew yellow;","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਅੰਤਰ ਪਿਯ ਕੀ ਪੀਰ ਨ ਪ੍ਰਗਟ ਜਤਾਵਈ।","roman":"Antar piy kee peer na pragat jataavaee |","meaning_en":"she did not openly show the pain of her beloved within,","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਸਾਤ ਸਮੁੰਦਰ ਪਾਰ ਪਿਯਾ ਤਾ ਕੋ ਰਹੈ।","roman":"Saat samundar paar piyaa taa ko rahai |","meaning_en":"her beloved lived beyond the seven seas;","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਆਨਿ ਮਿਲਾਵੈ ਤਾਹਿ ਇਤੋ ਦੁਖ ਕਿਹ ਕਹੈ। ੩੦।","roman":"Ho aani milaavai taahi ito dukh kih kahai | 30 |","meaning_en":"to whom could she say so great a sorrow, to have him come and meet her?","page":2069,"meaning_status":"draft"}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":2069,"lines":[{"gurmukhi":"ਅਬ ਕਹੋ ਬ੍ਰਿਥਾ ਕੁਅਰ ਕੀ ਕਛੁ ਸੁਨਿ ਲੀਜਿਯੈ।","roman":"Ab kaho brithaa kuar kee kachhu suni leejiyai |","meaning_en":"Now I tell something of the prince's distress; listen,","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਸੁਨਹੁ ਸੁਘਰ ਚਿਤ ਲਾਇ ਸ੍ਰਵਨ ਇਤ ਦੀਜਿਯੈ।","roman":"Sunhu sughar chit laai sravan it deejiyai |","meaning_en":"listen, wise one, with your mind fixed, give your ears to it.","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਰੋਤ ਰੋਤ ਨਿਸੁ ਦਿਨ ਸਭ ਸਜਨ ਬਿਤਾਵਈ।","roman":"Rot rot nisu din sabh sajan bitaavaee |","meaning_en":"Weeping, weeping, he passes all night and day,","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਪਰੈ ਨ ਤਾ ਕੋ ਹਾਥ ਚਿਤ੍ਰ ਉਰ ਲਾਵਈ। ੩੧।","roman":"Ho parai na taa ko haath chitr ur laavaee | 31 |","meaning_en":"and, not getting her, he holds her picture to his heart.","page":2069,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2069,"meaning_status":"draft"},{"type":"verse","number":[32],"number_text":"੩੨।","page":2069,"lines":[{"gurmukhi":"ਇਤੈ ਚਾਹ ਉਨ ਕੀ ਲਗੀ ਉਨ ਕੌ ਇਨ ਕੀ ਚਾਹ।","roman":"Itai chaah un kee lagee un kau in kee chaah |","meaning_en":"Here she longed for him, and he longed for her;","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਕਹੁ ਕੌਨੇ ਛਲ ਪਾਇਯੈ ਕਰਤਾ ਕਰੈ ਨਿਬਾਹ। ੩੨।","roman":"Kahu kaune chhal paaiyai kartaa karai nibaah | 32 |","meaning_en":"say by what trick they may meet; may the Creator carry it through.","page":2069,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2069,"meaning_status":"draft"},{"type":"verse","number":[33],"number_text":"੩੩।","page":2069,"lines":[{"gurmukhi":"ਅਤਿਥ ਭੇਸ ਧਰਿ ਪਰੀ ਕੁਅਰਿ ਕੇ ਢਿਗ ਗਈ।","roman":"Atith bhes dhari paree kuari ke dhig gaee |","meaning_en":"The fairy took the garb of an ascetic and went near the princess,","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜ ਸੁਤਾ ਕੀ ਬਾਤ ਬਤਾਵਤ ਤਿਹ ਭਈ।","roman":"Raaj sutaa kee baat bataavat tih bhaee |","meaning_en":"and told her about the king's daughter.","page":2069,"meaning_status":"draft","note":"ਰਾਜ ਸੁਤਾ ਕੀ ਬਾਤ: 'the matter of the king's daughter', as printed; the following lines speak of the prince's longing, so ਸੁਤਾ may be a slip for ਸੁਤ (prince); uncertain."},{"gurmukhi":"ਤੁਮ ਕੌ ਉਨ ਕੀ ਚਾਹ ਉਨੈ ਤੁਮਰੀ ਲਗੀ।","roman":"Tum kau un kee chaah unai tumree lagee |","meaning_en":"\"You long for him, and he for you;","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਿਸੁ ਦਿਨੁ ਜਪਤ ਬਿਹੰਗ ਜ੍ਯੋ ਪ੍ਰੀਤਿ ਤੈਸੀ ਜਗੀ। ੩੩।","roman":"Ho nisu dinu japat bihang jyo preeti taisee jagee | 33 |","meaning_en":"night and day he repeats your name, as a bird does, such is the love awakened.\"","page":2069,"meaning_status":"draft"}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":2069,"lines":[{"gurmukhi":"ਸਾਤ ਸਮੁੰਦ੍ਰਨ ਪਾਰ ਕੁਅਰਿ ਵਹ ਜਾਨਿਯੈ।","roman":"Saat samundran paar kuari vah jaaniyai |","meaning_en":"\"Know that prince to be beyond the seven seas;","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਨੇਹ ਲਗ੍ਯੋ ਤੁਮ ਸੋ ਤਿਹ ਅਧਿਕ ਪ੍ਰਮਾਨਿਯੈ।","roman":"Neh lagyo tum so tih adhik pramaaniyai |","meaning_en":"his love for you is held to be very great.","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਕਰਿ ਕਰਿ ਕੌਨ ਉਪਾਇ ਕਹੋ ਤਿਹ ਲ੍ਯਾਇਯੈ।","roman":"Kari kari kaun upaai kaho tih lyaaiyai |","meaning_en":"Tell me by what means he can be brought,","page":2069,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਰਾਜ ਕੁਅਰ ਸੁਕੁਮਾਰਿ ਸੁ ਕਿਹ ਬਿਧਿ ਪਾਇਯੈ। ੩੪।","roman":"Ho raaj kuar sukumaari su kih bidhi paaiyai | 34 |","meaning_en":"and how the tender prince can be obtained.\"","page":2069,"meaning_status":"draft"}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":2071,"lines":[{"gurmukhi":"ਮੁਹਿ ਸਰਦਾਰ ਪਰੀ ਕੀ ਸੁਰਿਦ ਬਖਾਨਿਯੈ।","roman":"Muhi sardaar paree kee surid bakhaaniyai |","meaning_en":"\"Know me as the chief's confidante (Sardar Pari),","page":2071,"meaning_status":"draft","note":"ਸਰਦਾਰ ਪਰੀ: 'Sardar Pari', the leader of the fairies; printed so. ਸੁਰਿਦ: read as 'confidante'; uncertain."},{"gurmukhi":"ਰਵਿ ਸਸਿ ਕੀ ਸਮ ਜਾ ਕੋ ਰੂਪ ਪ੍ਰਮਾਨਿਯੈ।","roman":"Ravi sasi kee sam jaa ko roop pramaaniyai |","meaning_en":"whose beauty is held equal to the sun's and moon's.","page":2071,"meaning_status":"draft"},{"gurmukhi":"ਜਬ ਵਹੁ ਰਾਜ ਕੁਅਰਿ ਕੀ ਚਿਤ ਨਿਰਖਤ ਭਈ।","roman":"Jab vahu raaj kuari kee chit nirkhat bhaee |","meaning_en":"When she saw the princess's picture,","page":2071,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਤਬ ਹੌ ਤੁਮਰੇ ਤੀਰ ਪਠਾਇ ਤੁਰਿਤ ਦਈ। ੩੫।","roman":"Ho tab hau tumre teer pathaai turit daee | 35 |","meaning_en":"then I sent her to you at once.\"","page":2071,"meaning_status":"draft","note":"Read as the speaker (the fairy) saying she herself was sent/came to the princess; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2071,"meaning_status":"draft"},{"type":"verse","number":[36],"number_text":"੩੬।","page":2071,"lines":[{"gurmukhi":"ਤੀਨਿ ਭਵਨ ਮੈ ਭ੍ਰਮਿ ਫਿਰੀ ਤਾ ਸਮ ਕਹੂੰ ਨ ਨਾਰਿ।","roman":"Teeni bhavan mai bhrami phiree taa sam kahoon na naari |","meaning_en":"\"I wandered through the three worlds; there is no woman like her anywhere;","page":2071,"meaning_status":"draft","note":"Speaker is Sardar Pari speaking to the prince, per the flow; printed so; uncertain of the addressee."},{"gurmukhi":"ਤਾ ਕੇ ਬਰਬੇ ਜੋਗ ਹੌ ਤੁਮ ਹੀ ਰਾਜ ਕੁਮਾਰ। ੩੬।","roman":"Taa ke barbe jog hau tum hee raaj kumaar | 36 |","meaning_en":"you alone, prince, are fit to marry her.\"","page":2071,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2071,"meaning_status":"draft"},{"type":"verse","number":[37],"number_text":"੩੭।","page":2071,"lines":[{"gurmukhi":"ਹੌ ਸਰਦਾਰ ਪਰੀ ਪਹਿ ਅਬ ਉਠ ਜਾਇ ਹੋ।","roman":"Hau sardaar paree pahi ab uth jaai ho |","meaning_en":"\"I, Sardar Pari, will rise and go to her now;","page":2071,"meaning_status":"draft"},{"gurmukhi":"ਕੁਅਰਿ ਜੋਗ ਬਰ ਲਹਿ ਤੁਹਿ ਤਾਹਿ ਬਤਾਇ ਹੋ।","roman":"Kuari jog bar lahi tuhi taahi bataai ho |","meaning_en":"I will find a fitting prince and tell it to her;","page":2071,"meaning_status":"draft","note":"Read as: she will find the princess a fitting match."},{"gurmukhi":"ਜਬ ਤੁਮ ਤਾ ਕਹ ਜਾਇ ਸਜਨ ਬਰਿ ਲੇਹੁਗੇ।","roman":"Jab tum taa kah jaai sajan bari lehuge |","meaning_en":"when you go and take that beloved as your bride,","page":2071,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਹਾ ਬਤਾਵਹੁ ਮੋਹਿ ਤਬੈ ਜਸੁ ਦੇਹੁਗੇ। ੩੭।","roman":"Ho kahaa bataavhu mohi tabai jasu dehuge | 37 |","meaning_en":"then you will tell me what you have done and give me praise.\"","page":2071,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2071,"meaning_status":"draft"},{"type":"verse","number":[38],"number_text":"੩੮।","page":2071,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਤਾ ਕੌ ਪਰੀ ਉਡਾਨੀ। ਸਿਵੀ ਬਾਸਵੀ ਰਵੀ ਪਛਾਨੀ।","roman":"Yau kahi taa kau paree udaanee | sivee baasvee ravee pachhaanee |","meaning_en":"Saying so, the fairy flew off; she was taken for Shivi, Indrani, or the sun's consort.","page":2071,"meaning_status":"draft"},{"gurmukhi":"ਚਲਿ ਸਰਦਾਰ ਪਰੀ ਪਹਿ ਆਈ। ਸਕਲ ਬ੍ਰਿਥਾ ਕਹਿ ਤਾਹਿ ਸੁਨਾਈ। ੩੮।","roman":"Chali sardaar paree pahi aaee | sakal brithaa kahi taahi sunaaee | 38 |","meaning_en":"She went and came to Sardar Pari, and told her the whole account.","page":2071,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2071,"meaning_status":"draft"},{"type":"verse","number":[39],"number_text":"੩੯।","page":2071,"lines":[{"gurmukhi":"ਤੀਨਿ ਲੋਕ ਮੈ ਖੋਜਿ ਕਰਿ ਸੁਘਰ ਲਖਾ ਇਕ ਠੌਰ।","roman":"Teeni lok mai khoji kari sughar lakhaa ik thaur |","meaning_en":"\"Having searched the three worlds I found a clever one in one place;","page":2071,"meaning_status":"draft"},{"gurmukhi":"ਚਲਿ ਕਰਿ ਆਪੁ ਨਿਹਾਰਿਯੈ ਜਾ ਸਮ ਸੁੰਦ੍ਰ ਨ ਔਰ। ੩੯।","roman":"Chali kari aapu nihaariyai jaa sam sundr na aur | 39 |","meaning_en":"go and see for yourself; there is no other beauty like him.\"","page":2071,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2071,"meaning_status":"draft"},{"type":"verse","number":[40],"number_text":"੪੦।","page":2071,"lines":[{"gurmukhi":"ਸੁਨਤ ਬਚਨ ਸਭ ਪਰੀ ਉਡਾਨੀ। ਸਾਤ ਸਮੁੰਦ੍ਰ ਪਾਰ ਨਿਜਕਾਨੀ।","roman":"Sunat bachan sabh paree udaanee | saat samundr paar nijkaanee |","meaning_en":"Hearing the words, the fairy flew off, to the place beyond the seven seas.","page":2071,"meaning_status":"draft"},{"gurmukhi":"ਜਬ ਦਿਲੀਪ ਸਿੰਘ ਨੈਨ ਨਿਹਾਰਾ। ਚਿਤ ਕੋ ਸੋਕ ਦੂਰ ਕਰਿ ਡਾਰਾ। ੪੦।","roman":"Jab dileep singh nain nihaaraa | chit ko sok door kari daaraa | 40 |","meaning_en":"When she saw Dilip Singh with her eyes, she cast away the sorrow of her heart.","page":2071,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2071,"meaning_status":"draft"},{"type":"verse","number":[41],"number_text":"੪੧।","page":2071,"lines":[{"gurmukhi":"ਅਪ੍ਰਮਾਨ ਦੁਤਿ ਕੁਅਰ ਕੀ ਅਟਕੀ ਪਰੀ ਨਿਹਾਰਿ।","roman":"Apramaan duti kuar kee atkee paree nihaari |","meaning_en":"Seeing the immeasurable radiance of the prince, the fairy was held fast:","page":2071,"meaning_status":"draft"},{"gurmukhi":"ਯਹਿ ਸੁੰਦਰਿ ਹਮ ਹੀ ਬਰੈ ਡਾਰੀ ਕੁਅਰਿ ਬਿਸਾਰਿ। ੪੧।","roman":"Yahi sundri ham hee barai daaree kuari bisaari | 41 |","meaning_en":"\"This beauty I will marry myself,\" she said, forgetting the princess.","page":2071,"meaning_status":"draft","note":"ਇਹ ਸੁੰਦਰਿ ਹਮ ਹੀ ਬਰੈ: printed so; read as the fairy thinking to wed the prince herself."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2071,"meaning_status":"draft"},{"type":"verse","number":[42],"number_text":"੪੨।","page":2071,"lines":[{"gurmukhi":"ਹਾਇ ਹਾਇ ਵਹੁ ਪਰੀ ਉਚਾਰੈ। ਦੈਦੈ ਮੂੰਡਿ ਧਰਨਿ ਸੌ ਮਾਰੈ।","roman":"Haai haai vahu paree uchaarai | daidai moondi dharni sau maarai |","meaning_en":"That fairy cried \"Alas, alas\" and beat her head on the ground.","page":2071,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਨਿਮਿਤ ਹਮ ਅਸ ਸ੍ਰਮ ਕੀਯਾ। ਸੋ ਬਿਧਿ ਤਾਹਿ ਨ ਭੇਟਨ ਦੀਯਾ। ੪੨।","roman":"Jih nimit ham as sram keeyaa | so bidhi taahi na bhetan deeyaa | 42 |","meaning_en":"\"For whose sake I took such trouble, the Creator has not let me meet him.\"","page":2071,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2071,"meaning_status":"draft"},{"type":"verse","number":[43],"number_text":"੪੩।","page":2071,"lines":[{"gurmukhi":"ਅਬ ਸਰਦਾਰ ਪਰੀ ਕਹੈ ਹੌ ਹੀ ਬਰਿਹੋ ਜਾਹਿ।","roman":"Ab sardaar paree kahai hau hee bariho jaahi |","meaning_en":"Now Sardar Pari says, \"I myself will marry him;","page":2071,"meaning_status":"draft"},{"gurmukhi":"ਪੀਰ ਕੁਅਰਿ ਕੀ ਨ ਕਰੈ ਲਾਜ ਨ ਆਵਤ ਤਾਹਿ। ੪੩।","roman":"Peer kuari kee na karai laaj na aavat taahi | 43 |","meaning_en":"I will not heed the princess's pain, I feel no shame.\"","page":2071,"meaning_status":"draft"}]},{"type":"verse","number":[44],"number_text":"੪੪।","page":2073,"lines":[{"gurmukhi":"ਸੁਨੁ ਸਰਦਾਰ ਪਰੀ ਜੁ ਹਮ ਜਿਹ ਹਿਤ ਅਤਿ ਸ੍ਰਮ ਕੀਨ।","roman":"Sunu sardaar paree ju ham jih hit ati sram keen |","meaning_en":"\"Listen, Sardar Pari: for whom we took such great trouble,","page":2073,"meaning_status":"draft","note":"Read as the fairy addressing herself, or a companion addressing her; uncertain."},{"gurmukhi":"ਅਬ ਤੈ ਯਾਹਿ ਬਰਿਯੋ ਚਹਤ ਮਿਲਨ ਨ ਤਾ ਕਹ ਦੀਨ। ੪੪।","roman":"Ab tai yaahi bariyo chahat milan na taa kah deen | 44 |","meaning_en":"now you wish to marry him yourself and did not let her meet him.\"","page":2073,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2073,"meaning_status":"draft"},{"type":"verse","number":[45],"number_text":"੪੫।","page":2073,"lines":[{"gurmukhi":"ਸਖਿ ਸਰਦਾਰ ਪਰੀ ਕ੍ਯਾ ਕਰੈ। ਬਿਰਹ ਤਾਪ ਤਨ ਛਤਿਯਾ ਜਰੈ।","roman":"Sakhi sardaar paree kyaa karai | birah taap tan chhatiyaa jarai |","meaning_en":"\"What can Sardar Pari do, friend? The heat of separation burns my breast.","page":2073,"meaning_status":"draft"},{"gurmukhi":"ਜਬ ਮੈ ਯਾ ਕੋ ਰੂਪ ਨਿਹਾਰਿਯੋ। ਸ੍ਵਰਗ ਬਿਖੈ ਕੋ ਬਾਸ ਬਿਸਾਰਿਯੋ। ੪੫।","roman":"Jab mai yaa ko roop nihaariyo | svarag bikhai ko baas bisaariyo | 45 |","meaning_en":"When I saw his beauty I forgot my dwelling in heaven.\"","page":2073,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2073,"meaning_status":"draft"},{"type":"verse","number":[46],"number_text":"੪੬।","page":2073,"lines":[{"gurmukhi":"ਕਹਾ ਕਰੋ ਮੈ ਜਾਉ ਕਤ ਲਗੈ ਨਿਗੋਡੇ ਨੈਨ।","roman":"Kahaa karo mai jaau kat lagai nigode nain |","meaning_en":"\"What shall I do, where shall I go? My eyes are caught fast;","page":2073,"meaning_status":"draft","note":"ਨਿਗੋਡੇ: 'wretched, unlucky'; read as 'caught/stuck'; uncertain."},{"gurmukhi":"ਬਿਨੁ ਹੇਰੇ ਕਲ ਨ ਪਰੈ ਨਿਰਖਤ ਲਾਗਤ ਚੈਨ। ੪੬।","roman":"Binu here kal na parai nirkhat laagat chain | 46 |","meaning_en":"without seeing him I have no peace; looking at him I find rest.","page":2073,"meaning_status":"draft"}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":2073,"lines":[{"gurmukhi":"ਬਿਨ ਦੇਖੇ ਮਹਬੂਬ ਕੇ ਪਲਕ ਲਗਤ ਹੈ ਜਾਮ।","roman":"Bin dekhe mahboob ke palak lagat hai jaam |","meaning_en":"Without seeing the beloved, one watch seems like a blink in length;","page":2073,"meaning_status":"draft","note":"ਪਲਕ ਲਗਤ ਹੈ ਜਾਮ: 'a blink takes a watch'; read as a moment dragging as long as a watch (three hours); uncertain."},{"gurmukhi":"ਤਬ ਸਰਦਾਰ ਪਰੀ ਹੁਤੀ ਅਬ ਇਹ ਭਈ ਗੁਲਾਮ। ੪੭।","roman":"Tab sardaar paree hutee ab ih bhaee gulaam | 47 |","meaning_en":"I was Sardar Pari then; now I have become his slave.\"","page":2073,"meaning_status":"draft"}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":2073,"lines":[{"gurmukhi":"ਕਹਾ ਕਰੌ ਕਾ ਸੌ ਕਹੌ ਕਹੇ ਨ ਆਵਤ ਬੈਨ।","roman":"Kahaa karau kaa sau kahau kahe na aavat bain |","meaning_en":"\"What shall I do, to whom shall I tell it? No words come to speak it;","page":2073,"meaning_status":"draft"},{"gurmukhi":"ਬਿਨੁ ਦੇਖੇ ਮਹਬੂਬ ਕੇ ਭਏ ਜਹਮਤੀ ਨੈਨ। ੪੮।","roman":"Binu dekhe mahboob ke bhae jahamtee nain | 48 |","meaning_en":"without seeing the beloved my eyes have been in anguish.\"","page":2073,"meaning_status":"draft","note":"ਜਹਮਤੀ: from Persian zahmat, 'trouble, affliction'; read so."}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2073,"meaning_status":"draft"},{"type":"verse","number":[49],"number_text":"੪੯।","page":2073,"lines":[{"gurmukhi":"ਪਲਕ ਨ ਇਤ ਉਤ ਜਾਇ ਨੈਨ ਐਸੇ ਲਗੇ।","roman":"Palak na it ut jaai nain aise lage |","meaning_en":"They do not move this way or that, even for a blink; my eyes are so fixed;","page":2073,"meaning_status":"draft"},{"gurmukhi":"ਪਿਯ ਦੇਖਨ ਕੇ ਪ੍ਰੇਮ ਦੋਊ ਇਹ ਬਿਧਿ ਪਗੇ।","roman":"Piy dekhan ke prem do'oo ih bidhi page |","meaning_en":"both are so steeped in love for seeing the beloved.","page":2073,"meaning_status":"draft"},{"gurmukhi":"ਲਗਨ ਲਾਗਿ ਮੁਰਿ ਗਈ ਨਿਗੋਡਿ ਨ ਛੂਟਈ।","roman":"Lagan laagi muri gaee nigodi na chhootaee |","meaning_en":"Struck by longing, I am turned back; the wretched ones do not let go;","page":2073,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨੈਕੁ ਨਿਹਾਰੇ ਬਿਨੁ ਸਖਿ ਪ੍ਰਾਨ ਨਿਖੂਟਈ। ੪੯।","roman":"Ho naiku nihaare binu sakhi praan nikhootaee | 49 |","meaning_en":"without seeing him even a little, friend, my life is spent.","page":2073,"meaning_status":"draft"}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":2073,"lines":[{"gurmukhi":"ਛੁਟਤ ਛੁਟਾਏ ਨਾਹਿ ਨਿਗੋਡੇ ਜਹ ਲਗੇ।","roman":"Chhutat chhutaae naahi nigode jah lage |","meaning_en":"Though wretched, they are not freed by freeing, wherever they are fixed;","page":2073,"meaning_status":"draft"},{"gurmukhi":"ਪਲਕ ਨ ਇਤ ਉਤ ਹੋਇ ਪ੍ਰੇਮ ਪਿਯ ਕੇ ਪਗੇ।","roman":"Palak na it ut hoi prem piy ke page |","meaning_en":"not a blink moves them this way or that, steeped in love of the beloved;","page":2073,"meaning_status":"draft"},{"gurmukhi":"ਜਹਾ ਲਗੇ ਏ ਨੈਨ ਤਹੀ ਕੈ ਹ੍ਵੈ ਰਹੇ।","roman":"Jahaa lage e nain tahee kai hvai rahe |","meaning_en":"wherever these eyes have fixed, they have become that place's own;","page":2073,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਫਿਰਿ ਆਵਨ ਕੇ ਨਾਹਿ ਕਬਿਨ ਐਸੇ ਕਹੇ। ੫੦।","roman":"Ho phiri aavan ke naahi kabin aise kahe | 50 |","meaning_en":"they will not come back, so poets have said.","page":2073,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2073,"meaning_status":"draft"},{"type":"verse","number":[51],"number_text":"੫੧।","page":2073,"lines":[{"gurmukhi":"ਥਰਹਰਾਇ ਥਿਰ ਨ ਰਹਹਿ ਪਲਕ ਨਹੀ ਠਹਰਾਹਿ।","roman":"Tharahraai thir na rahhi palak nahee thahraahi |","meaning_en":"Trembling, they do not stay steady, a blink does not stay;","page":2073,"meaning_status":"draft"},{"gurmukhi":"ਜਹ ਲਾਗੇ ਏ ਲੋਇਨਾ ਫਿਰਿ ਆਵਨ ਕੇ ਨਾਹਿ। ੫੧।","roman":"Jah laage e loinaa phiri aavan ke naahi | 51 |","meaning_en":"where these eyes have fixed, they will not return.","page":2073,"meaning_status":"draft"}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":2073,"lines":[{"gurmukhi":"ਨਿਰਖਿ ਨੈਨ ਮਹਬੂਬ ਕੇ ਨੈਨ ਗਡੇ ਤਿਨ ਮਾਹਿ।","roman":"Nirkhi nain mahboob ke nain gade tin maahi |","meaning_en":"Seeing the eyes of the beloved, her eyes were fixed in them;","page":2073,"meaning_status":"draft"},{"gurmukhi":"ਉਡੈ ਅਘਾਨੇ ਬਾਜ ਜ੍ਯੋ ਫਿਰ ਆਵਨ ਕੇ ਨਾਹਿ। ੫੨।","roman":"Udai aghaane baaj jyo phir aavan ke naahi | 52 |","meaning_en":"like a sated hawk they fly off and will not come back.","page":2073,"meaning_status":"draft"}]},{"type":"verse","number":[53],"number_text":"੫੩।","page":2073,"lines":[{"gurmukhi":"ਜਹਾ ਲਗੇ ਏ ਲੋਇਨਾ ਤਹ ਹੀ ਕੇ ਸੁ ਭਏ।","roman":"Jahaa lage e loinaa tah hee ke su bhae |","meaning_en":"Where these eyes fixed, there they have become that place's own;","page":2073,"meaning_status":"draft"},{"gurmukhi":"ਬਹਰੀ ਜ੍ਯੋ ਕਹਰੀ ਦੋਊ ਗਏ ਸੁ ਗਏ ਗਏ। ੫੩।","roman":"Bahree jyo kahree do'oo gae su gae gae | 53 |","meaning_en":"like the deaf and the miserable, both went and are gone, gone.","page":2073,"meaning_status":"draft","note":"ਬਹਰੀ ਜ੍ਯੋ ਕਹਰੀ: printed so; 'like the deaf one, like the afflicted'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2073,"meaning_status":"draft"},{"type":"verse","number":[54],"number_text":"੫੪।","page":2073,"lines":[{"gurmukhi":"ਜਿਤ ਲਾਗੇ ਏ ਨੈਨ ਸੁ ਤਿਤਹੀ ਕੇ ਭਏ।","roman":"Jit laage e nain su tithee ke bhae |","meaning_en":"Wherever these eyes fixed, they became that place's own;","page":2073,"meaning_status":"draft"},{"gurmukhi":"ਕਰਿ ਹਾਰੀ ਹੌ ਜਤਨ ਨ ਭੂਲਿ ਇਤੈ ਅਏ।","roman":"Kari haaree hau jatan na bhooli itai ae |","meaning_en":"I am tired of trying; they do not even by mistake come back here.","page":2073,"meaning_status":"draft"},{"gurmukhi":"ਛੁਟੀ ਬਾਤ ਮੁਰਿ ਕਰ ਤੇ ਕਹੋ ਹੌ ਕ੍ਯਾ ਕਰੋ।","roman":"Chhutee baat muri kar te kaho hau kyaa karo |","meaning_en":"The matter has slipped from my hand; tell me what shall I do?","page":2073,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਮਦਨ ਤਾਪ ਤਨ ਤਈ ਸਦਾ ਜਿਯ ਮੈ ਜਰੋ। ੫੪।","roman":"Ho madan taap tan taee sadaa jiy mai jaro | 54 |","meaning_en":"The heat of love scorches my body; I always burn within.","page":2073,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2075,"meaning_status":"draft"},{"type":"verse","number":[55],"number_text":"੫੫।","page":2075,"lines":[{"gurmukhi":"ਕੋਟਿ ਜਤਨ ਕਰਿ ਰਹੀ ਸਖੀ ਸਬ। ਲਗਨ ਨਿਗੌਡੀ ਲਾਗਿ ਗਈ ਜਬ।","roman":"Koti jatan kari rahee sakhee sab | lagan nigaudee laagi gaee jab |","meaning_en":"All her friends tried ten million means, but when the unlucky longing had taken hold,","page":2075,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਤਿਨ ਪਰੀ ਉਪਾਇ ਬਿਚਾਰੋ। ਰਾਜ ਪੁਤ੍ਰ ਸੌ ਜਾਇ ਉਚਾਰੋ। ੫੫।","roman":"Tab tin paree upaai bichaaro | raaj putr sau jaai uchaaro | 55 |","meaning_en":"then the fairy thought of a plan: she would go and tell the prince.","page":2075,"meaning_status":"draft"}]},{"type":"verse","number":[56],"number_text":"੫੬।","page":2075,"lines":[{"gurmukhi":"ਰਾਜ ਕੁਅਰ ਤੈ ਜਿਹ ਬਰ ਲਾਇਕ। ਜਾ ਕੀ ਪਰੀ ਲਗਹਿ ਸਭ ਪਾਇਕ।","roman":"Raaj kuar tai jih bar laaik | jaa kee paree laghi sabh paaik |","meaning_en":"\"Prince, you who are worthy of a bride, at whose feet all fairies bow,","page":2075,"meaning_status":"draft","note":"ਪਾਇਕ: 'footmen/servants'."},{"gurmukhi":"ਅਬ ਤੁਹਿ ਬਰਿਯੋ ਚਹਤ ਹਮਰੀ ਪਤਿ। ਕਹਾ ਤਿਹਾਰੇ ਆਵਤ ਹੈ ਮਤਿ। ੫੬।","roman":"Ab tuhi bariyo chahat hamree pati | kahaa tihaare aavat hai mati | 56 |","meaning_en":"now my mistress (the princess, i.e. the fairy herself) wishes to marry you; what sense comes to you?\"","page":2075,"meaning_status":"draft","note":"ਹਮਰੀ ਪਤਿ: 'my lady/lord'; unclear; read as the fairy speaking of herself or her chief; uncertain."}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":2075,"lines":[{"gurmukhi":"ਰਾਜ ਕੁਅਰ ਇਹ ਭਾਤਿ ਸੁਨਾ ਜਬ। ਬਚਨ ਪਰੀ ਸੋ ਕਹੇ ਬਿਹਸਿ ਤਬ।","roman":"Raaj kuar ih bhaati sunaa jab | bachan paree so kahe bihsi tab |","meaning_en":"When the prince heard this, he said to the fairy, smiling:","page":2075,"meaning_status":"draft"},{"gurmukhi":"ਮੈ ਸਰਦਾਰ ਪਰਿਹਿ ਨਹਿ ਬਰਿ ਹੌ। ਲਾਗਿ ਬਿਰਹ ਸੁ ਕੁਅਰਿ ਕੇ ਮਰਿ ਹੌ। ੫੭।","roman":"Mai sardaar parihi nahi bari hau | laagi birah su kuari ke mari hau | 57 |","meaning_en":"\"I will not marry Sardar Pari; in separation from the princess I will die.\"","page":2075,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2075,"meaning_status":"draft"},{"type":"verse","number":[58],"number_text":"੫੮।","page":2075,"lines":[{"gurmukhi":"ਲਾਗ ਕੁਅਰਿ ਕੇ ਬਿਰਹ ਤਨ ਬਰਿ ਹੌ ਦਿਨ ਅਰੁ ਰੈਨਿ।","roman":"Laag kuari ke birah tan bari hau din aru raini |","meaning_en":"\"I will burn in body day and night in separation from the princess;","page":2075,"meaning_status":"draft"},{"gurmukhi":"ਕਹਾ ਭਯੋ ਇਹ ਜੌ ਪਰੀ ਨੈਕ ਨ ਲਗਿਹੈ ਨੈਨ। ੫੮।","roman":"Kahaa bhayo ih jau paree naik na lagihai nain | 58 |","meaning_en":"what does it matter, fairy, if my eyes never settle on you.\"","page":2075,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2075,"meaning_status":"draft"},{"type":"verse","number":[59],"number_text":"੫੯।","page":2075,"lines":[{"gurmukhi":"ਕਹਾ ਪਰੀ ਇਕ ਮੋਰ ਕਹਾ ਕਰੁ। ਰਾਜ ਕੁਅਰ ਤੈ ਰਾਜ ਪਰੀ ਬਰੁ।","roman":"Kahaa paree ik mor kahaa karu | raaj kuar tai raaj paree baru |","meaning_en":"\"What is one fairy to me? What can I do with one? Prince, marry a royal fairy.\"","page":2075,"meaning_status":"draft","note":"Read as the fairy's plea, then the prince's reply; the speaker is not marked."},{"gurmukhi":"ਰਾਜ ਕੁਅਰਿ ਕਹੁ ਬਰਿ ਕਸ ਕਰਿ ਹੈ। ਪਦਮਿਨਿ ਛਾਡਿ ਹਸਤਿਨੀ ਬਰਿਹੈ। ੫੯।","roman":"Raaj kuari kahu bari kas kari hai | padmini chhaadi hastinee barihai | 59 |","meaning_en":"\"How would a princess marry? She would leave the lotus-woman and marry an elephant-woman.\"","page":2075,"meaning_status":"draft","note":"ਪਦਮਿਨਿ / ਹਸਤਿਨੀ: Padmini and Hastini, two types of women in the Koka classification; read so; uncertain who speaks."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2075,"meaning_status":"draft"},{"type":"verse","number":[60],"number_text":"੬੦।","page":2075,"lines":[{"gurmukhi":"ਜਾ ਸੌ ਮੇਰੋ ਹਿਤ ਲਗਾ ਵਹੈ ਹਮਾਰੀ ਨਾਰਿ।","roman":"Jaa sau mero hit lagaa vahai hamaaree naari |","meaning_en":"\"She with whom my love is fixed is my wife;","page":2075,"meaning_status":"draft"},{"gurmukhi":"ਸੁਰੀ ਆਸੁਰੀ ਪਦਮਿਨੀ ਪਰੀ ਨ ਬਰੌ ਹਜਾਰ। ੬੦।","roman":"Suree aasuree padminee paree na barau hajaar | 60 |","meaning_en":"I would not marry a goddess, a demoness, a Padmini or a fairy, not if there were thousands.\"","page":2075,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2075,"meaning_status":"draft"},{"type":"verse","number":[61],"number_text":"੬੧।","page":2075,"lines":[{"gurmukhi":"ਪਰੀ ਜਤਨ ਕਰਿ ਕਰਿ ਬਹੁ ਹਾਰੀ। ਏਕ ਬਾਤ ਤਬ ਔਰ ਬਿਚਾਰੀ।","roman":"Paree jatan kari kari bahu haaree | ek baat tab aur bichaaree |","meaning_en":"The fairy, tired of trying many ways, then thought of another thing:","page":2075,"meaning_status":"draft"},{"gurmukhi":"ਜੌ ਇਹ ਕਹਤ ਵਹੈ ਹੌ ਕਰੌ। ਬਹੁਰੋ ਛਲਿ ਯਾਹੀ ਕਹ ਬਰੌ। ੬੧।","roman":"Jau ih kahat vahai hau karau | bahuro chhali yaahee kah barau | 61 |","meaning_en":"\"I will do whatever he says, and later marry him by a trick.\"","page":2075,"meaning_status":"draft"}]},{"type":"verse","number":[62],"number_text":"੬੨।","page":2075,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਪਰੀ ਜੋ ਤਹਾ ਪਠਾਈ। ਵਹੈ ਆਪਨੇ ਤੀਰ ਬੁਲਾਈ।","roman":"Pratham paree jo tahaa pathaaee | vahai aapne teer bulaaee |","meaning_en":"She called near her the first fairy whom she had sent there,","page":2075,"meaning_status":"draft"},{"gurmukhi":"ਤਾਹਿ ਕਹਾ ਜੁ ਕਹਾ ਮੁਰ ਕਰਿ ਹੈ। ਤਬ ਤਵ ਦੈਵ ਧਾਮ ਧਨ ਭਰਿ ਹੈ। ੬੨।","roman":"Taahi kahaa ju kahaa mur kari hai | tab tav daiv dhaam dhan bhari hai | 62 |","meaning_en":"and told her, \"If you do what I say, then God will fill your house with wealth.","page":2075,"meaning_status":"draft"}]},{"type":"verse","number":[63],"number_text":"੬੩।","page":2075,"lines":[{"gurmukhi":"ਯਾਹਿ ਕੁਅਰ ਮੁਹਿ ਦੇਹੁ ਮਿਲਾਈ। ਹੌ ਯਾ ਪਰ ਜਿਯ ਤੇ ਉਰਝਾਈ।","roman":"Yaahi kuar muhi dehu milaaee | hau yaa par jiy te urjhaaee |","meaning_en":"Unite this prince with me; I am entangled in him with my whole life.","page":2075,"meaning_status":"draft"},{"gurmukhi":"ਕਹਾ ਹਮਾਰਾ ਕਰੈ ਪ੍ਯਾਰੀ। ਤੂ ਸਾਹਿਬ ਮੈ ਦਾਸ ਤਿਹਾਰੀ। ੬੩।","roman":"Kahaa hamaaraa karai pyaaree | too saahib mai daas tihaaree | 63 |","meaning_en":"What can you do for me, dear? You are the mistress, I your slave.\"","page":2075,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2075,"meaning_status":"draft"},{"type":"verse","number":[64],"number_text":"੬੪।","page":2075,"lines":[{"gurmukhi":"ਸੁਨਤ ਬਚਨ ਇਹ ਪਰੀ ਫੂਲਿ ਮਨ ਮੈ ਗਈ।","roman":"Sunat bachan ih paree phooli man mai gaee |","meaning_en":"Hearing these words the fairy swelled with joy in her mind,","page":2075,"meaning_status":"draft"},{"gurmukhi":"ਸੁਘਰ ਕੁਅਰ ਕੇ ਪਾਸ ਜਾਤ ਤਬ ਹੀ ਭਈ।","roman":"Sughar kuar ke paas jaat tab hee bhaee |","meaning_en":"and went at once to the clever prince.","page":2075,"meaning_status":"draft"},{"gurmukhi":"ਪਰ ਪਾਇਨ ਕਰ ਜੋਰ ਕਹਾ ਮੁਸਕਾਇ ਕੈ।","roman":"Par paain kar jor kahaa muskaai kai |","meaning_en":"She fell at his feet, folded her hands, and said smiling,","page":2075,"meaning_status":"draft"},{"gurmukhi":"ਹੌ ਕਰੌ ਬਿਨਤਿ ਜੌ ਕਹੌ ਕਛੂ ਸਕੁਚਾਇ ਕੈ। ੬੪।","roman":"Hau karau binti jau kahau kachhoo sakuchaai kai | 64 |","meaning_en":"\"I make a request, if I speak a little hesitantly.","page":2075,"meaning_status":"draft"}]},{"type":"verse","number":[65],"number_text":"੬੫।","page":2077,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਪਰੀ ਸੌ ਕੁਅਰ ਤੁਮੈਸ ਉਚਾਰਿਯਹੁ।","roman":"Pratham paree sau kuar tumais uchaariyhu |","meaning_en":"First, prince, you should say to the fairy,","page":2077,"meaning_status":"draft","note":"ਪ੍ਰਥਮ ਪਰੀ ਸੌ ਕੁਅਰ ਤੁਮੈਸ ਉਚਾਰਿਯਹੁ: instruction the fairy gives the prince; read so."},{"gurmukhi":"ਗਹਿ ਬਹਿਯਾ ਸਿਹਜਾ ਪਰ ਤਿਹ ਬੈਠਾਰਿਯਹੁ।","roman":"Gahi bahiyaa sihjaa par tih baithaariyhu |","meaning_en":"taking her by the arm, seat her on the bed;","page":2077,"meaning_status":"draft"},{"gurmukhi":"ਰਮਿਯੋ ਚਹੈ ਤੁਮ ਸੌ ਤਬ ਤੁਮ ਯੌ ਭਾਖਿਯਹੁ।","roman":"Ramiyo chahai tum sau tab tum yau bhaakhiyhu |","meaning_en":"when she wishes to enjoy you, then you should say this:","page":2077,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਘਰੀ ਚਾਰਿ ਪਾਂਚਕ ਲਗਿ ਦ੍ਰਿੜ ਚਿਤ ਰਾਖਿਯਹੁ। ੬੫।","roman":"Ho gharee chaari paanchak lagi drir chit raakhiyhu | 65 |","meaning_en":"keep your mind firm for four or five ghari.","page":2077,"meaning_status":"draft"}]},{"type":"verse","number":[66],"number_text":"੬੬।","page":2077,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਬ੍ਯਾਹ ਤਾ ਸੌ ਜੌ ਮੋਰ ਕਰਾਇਹੋ।","roman":"Pratham byaah taa sau jau mor karaaiho |","meaning_en":"\"If you first have my marriage done with her (the princess),","page":2077,"meaning_status":"draft"},{"gurmukhi":"ਬਰਿਯੋ ਚਹਹੁ ਜੌ ਮੋਹਿ ਤੁ ਤਬਹੀ ਪਾਇਹੋ।","roman":"Bariyo chahhu jau mohi tu tabhee paaiho |","meaning_en":"then if you wish to marry me, you shall have me;","page":2077,"meaning_status":"draft"},{"gurmukhi":"ਤਾਹਿ ਬਰੇ ਬਿਨ ਮੈ ਨ ਤੋਹਿ ਕ੍ਯੋ ਹੂੰ ਬਰੋ।","roman":"Taahi bare bin mai na tohi kyo hoon baro |","meaning_en":"without marrying her I will not by any means marry you,","page":2077,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਾਤਰ ਮਾਰਿ ਕਟਾਰੀ ਉਰ ਅਬ ਹੀ ਮਰੋ। ੬੬।","roman":"Ho naatar maari kataaree ur ab hee maro | 66 |","meaning_en":"or else I will strike a dagger in my breast and die right now.\"","page":2077,"meaning_status":"draft"}]},{"type":"verse","number":[67],"number_text":"੬੭।","page":2077,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਭੇਦ ਕੁਅਰ ਦੈ ਤਾ ਕੇ ਢਿਗ ਗਈ।","roman":"Ih bidhi bhed kuar dai taa ke dhig gaee |","meaning_en":"Thus she gave the prince the secret and went to the other one,","page":2077,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਤਿਹ ਸਹਚਰਿ ਜਾਨਿ ਪਠੈ ਇਹ ਪੈ ਦਈ।","roman":"Jih tih sahachri jaani pathai ih pai daee |","meaning_en":"to the friend (fairy) who had been sent and had given herself to this one.","page":2077,"meaning_status":"draft","note":"Obscure; read as the fairy returning to the other fairy who had sent her; uncertain."},{"gurmukhi":"ਮੈ ਕਰਿ ਜਤਨ ਅਨੇਕ ਕੁਅਰਹਿ ਰਿਝਾਇਯੋ।","roman":"Mai kari jatan anek kuarhi rijhaaiyo |","meaning_en":"\"I have tried many means and won over the prince,","page":2077,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਤੁਮ ਸੋ ਕਰਨ ਕਲੋਲ ਕਬੂਲ ਕਰਾਇਯੋ। ੬੭।","roman":"Ho tum so karan kalol kabool karaaiyo | 67 |","meaning_en":"and made him agree to play love-sport with you.\"","page":2077,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2077,"meaning_status":"draft"},{"type":"verse","number":[68],"number_text":"੬੮।","page":2077,"lines":[{"gurmukhi":"ਸਾਹ ਪਰੀ ਕਹ ਲੈ ਤਹ ਆਈ। ਜਹਾ ਕੁਅਰ ਕੀ ਸੇਜ ਸੁਹਾਈ।","roman":"Saah paree kah lai tah aaee | jahaa kuar kee sej suhaaee |","meaning_en":"She took Shah Pari there, where the prince's bed was beautifully laid,","page":2077,"meaning_status":"draft"},{"gurmukhi":"ਤਹਾ ਕਪੂਰ ਅਰਗਜਾ ਮਹਿਕੈ। ਬਾਧੀ ਧੁਜਾ ਧਾਮ ਪਰ ਲਹਿਕੈ। ੬੮।","roman":"Tahaa kapoor aragjaa mahikai | baadhee dhujaa dhaam par lahikai | 68 |","meaning_en":"where camphor and agarwood were fragrant, and a flag was tied and waved on the roof of the house.","page":2077,"meaning_status":"draft","note":"ਅਰਗਜਾ: a perfume (aragaja, mixed fragrance)."}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":2077,"lines":[{"gurmukhi":"ਇਹ ਬਿਧਿ ਦੀਨਾ ਕੁਅਰ ਮਿਲਾਈ। ਬੈਠੇ ਦੋਊ ਸੇਜ ਪਰ ਜਾਈ।","roman":"Ih bidhi deenaa kuar milaaee | baithe do'oo sej par jaaee |","meaning_en":"In this way she brought the prince together with her; both sat on the bed.","page":2077,"meaning_status":"draft"},{"gurmukhi":"ਤਹ ਤੇ ਜਬੈ ਸਖੀ ਤਰਿ ਗਈ। ਕਾਮ ਕਰਾ ਤਾ ਕੇ ਤਨ ਭਈ। ੬੯।","roman":"Tah te jabai sakhee tari gaee | kaam karaa taa ke tan bhaee | 69 |","meaning_en":"When the friend had slipped away from there, desire came on her body.","page":2077,"meaning_status":"draft"}]},{"type":"verse","number":[70],"number_text":"੭੦।","page":2077,"lines":[{"gurmukhi":"ਕਾਮ ਪਰੀ ਕਹ ਜਬੈ ਸੰਤਾਯੋ। ਹਾਥ ਕੁਅਰ ਕੀ ਓਰ ਚਲਾਯੋ।","roman":"Kaam paree kah jabai santaayo | haath kuar kee or chalaayo |","meaning_en":"When desire tormented the fairy, she moved her hand toward the prince.","page":2077,"meaning_status":"draft"},{"gurmukhi":"ਬਿਹਸਿ ਕੁਅਰ ਇਹ ਭਾਤਿ ਉਚਾਰੀ। ਕਹੋ ਬਾਤ ਤੁਹਿ ਸੁਨਹੁ ਪ੍ਯਾਰੀ। ੭੦।","roman":"Bihsi kuar ih bhaati uchaaree | kaho baat tuhi sunhu pyaaree | 70 |","meaning_en":"The prince smiled and said, \"Listen, dear, to what I tell you:","page":2077,"meaning_status":"draft"}]},{"type":"verse","number":[71],"number_text":"੭੧।","page":2077,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਮੋਹਿ ਤੁਮ ਤਾਹਿ ਮਿਲਾਵਹੁ। ਬਹੁਰਿ ਭੋਗ ਮੁਰਿ ਸੰਗ ਕਮਾਵਹੁ।","roman":"Pratham mohi tum taahi milaavhu | bahuri bhog muri sang kamaavhu |","meaning_en":"\"First unite me with her, then enjoy me;","page":2077,"meaning_status":"draft"},{"gurmukhi":"ਪਹਿਲੇ ਬਰੋ ਵਹੈ ਬਰ ਨਾਰੀ। ਵਹ ਇਸਤ੍ਰੀ ਤੈ ਯਾਰ ਹਮਾਰੀ। ੭੧।","roman":"Pahile baro vahai bar naaree | vah istree tai yaar hamaaree | 71 |","meaning_en":"first I will marry that excellent woman; that woman is my beloved.\"","page":2077,"meaning_status":"draft","note":"ਯਾਰ: 'friend/lover'."}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2077,"meaning_status":"draft"},{"type":"verse","number":[72],"number_text":"੭੨।","page":2077,"lines":[{"gurmukhi":"ਕਰਿ ਹਾਰੀ ਬਹੁ ਜਤਨ ਨ ਤਿਹ ਰਤਿ ਵਹਿ ਦਈ।","roman":"Kari haaree bahu jatan na tih rati vahi daee |","meaning_en":"Having tried much, she did not give him love-making; she accepted what the prince said;","page":2077,"meaning_status":"draft","note":"ਤਿਹ ਰਤਿ ਵਹਿ ਦਈ: printed so, 'he gave her no union'; read as she failed to get the union; uncertain."},{"gurmukhi":"ਜੁ ਕਛੁ ਬਖਾਨੀ ਕੁਅਰ ਵਹੈ ਮਾਨਤ ਭਈ।","roman":"Ju kachhu bakhaanee kuar vahai maanat bhaee |","meaning_en":"she accepted whatever the prince had said,","page":2077,"meaning_status":"draft"},{"gurmukhi":"ਪਛਨ ਪਰ ਬੈਠਾਇ ਤਾਹਿ ਲੈਗੀ ਤਹਾ।","roman":"Pachhan par baithaai taahi laigee tahaa |","meaning_en":"seated him on her wings and took him to where the princess was,","page":2077,"meaning_status":"draft","note":"ਪਛਨ: 'wings'."},{"gurmukhi":"ਹੋ ਪਿਯ ਪਿਯ ਰਟਤ ਬਿਹੰਗ ਜ੍ਯੋ ਕੁਅਰਿ ਪਰੀ ਜਹਾ। ੭੨।","roman":"Ho piy piy ratat bihang jyo kuari paree jahaa | 72 |","meaning_en":"who cried 'beloved, beloved' like a bird, the princess in that place.","page":2077,"meaning_status":"draft"}]},{"type":"verse","number":[73],"number_text":"੭੩।","page":2077,"lines":[{"gurmukhi":"ਚਿਤ੍ਰ ਜਵਨ ਕੋ ਹੇਰਿ ਮੁਹਬਤਿ ਲਗਤ ਭੀ।","roman":"Chitr javan ko heri muhabti lagat bhee |","meaning_en":"As she had seen the portrait of the Yavana (the prince) and fallen in love,","page":2077,"meaning_status":"draft","note":"ਜਵਨ: 'Yavana, a foreigner/Muslim'; printed so, read as the prince; uncertain."},{"gurmukhi":"ਤਾ ਕੋ ਦਰਸ ਪ੍ਰਤਛਿ ਜਬੈ ਪਾਵਤ ਭਈ।","roman":"Taa ko daras pratchhi jabai paavat bhaee |","meaning_en":"so when she found his sight in person,","page":2077,"meaning_status":"draft"},{"gurmukhi":"ਕੁਅਰਿ ਚਹਤ ਜੋ ਹੁਤੀ ਬਿਧਾਤੈ ਸੋ ਕਰੀ।","roman":"Kuari chahat jo hutee bidhaatai so karee |","meaning_en":"the princess's wish, which the Creator had made, was fulfilled,","page":2077,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਬਨ ਬਸੰਤ ਕੀ ਭਾਤਿ ਸੁ ਝਰਿ ਝਰਿ ਭੀ ਹਰੀ। ੭੩।","roman":"Ho ban basant kee bhaati su jhari jhari bhee haree | 73 |","meaning_en":"and, like the forest in spring, she bloomed green again.","page":2077,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2079,"meaning_status":"draft"},{"type":"verse","number":[74],"number_text":"੭੪।","page":2079,"lines":[{"gurmukhi":"ਜਬ ਦਰਸਨ ਤ੍ਰਿਯ ਕਾ ਪਿਯ ਕਰਾ। ਖਾਨ ਪਾਨ ਆਗੇ ਲੈ ਧਰਾ।","roman":"Jab darsan triy kaa piy karaa | khaan paan aage lai dharaa |","meaning_en":"When the beloved had seen the woman, she set food and drink before him;","page":2079,"meaning_status":"draft"},{"gurmukhi":"ਬਿਬਿਧ ਬਿਧਨ ਕੇ ਅਮਲ ਮੰਗਾਏ। ਬੈਠਿ ਕੁਅਰਿ ਕੇ ਤੀਰ ਚੜਾਏ। ੭੪।","roman":"Bibidh bidhan ke amal mangaae | baithi kuari ke teer charaae | 74 |","meaning_en":"she had various kinds of intoxicants brought and sat near the princess, offering them.","page":2079,"meaning_status":"draft","note":"ਅਮਲ: intoxicants such as opium; printed so."}]},{"type":"verse","number":[75],"number_text":"੭੫।","page":2079,"lines":[{"gurmukhi":"ਤਾਹੂ ਕੋ ਬਹੁ ਕੈਫ ਪਿਵਾਈ। ਬਹੁਰੋ ਲਯੋ ਗਰੇ ਸੋ ਲਾਈ।","roman":"Taahoo ko bahu kaiph pivaaee | bahuro layo gare so laaee |","meaning_en":"She made him drink much too, and then took him to her breast;","page":2079,"meaning_status":"draft"},{"gurmukhi":"ਆਸਨ ਚੁੰਬਨ ਬਹੁ ਬਿਧਿ ਕੀਏ। ਚਿਤ ਕੇ ਤਾਪ ਬਿਦਾ ਕਰਿ ਦੀਏ। ੭੫।","roman":"Aasan chunban bahu bidhi kee'e | chit ke taap bidaa kari dee'e | 75 |","meaning_en":"they took postures and kissed in many ways and sent away the heat of their hearts.","page":2079,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2079,"meaning_status":"draft"},{"type":"verse","number":[76],"number_text":"੭੬।","page":2079,"lines":[{"gurmukhi":"ਕੁਅਰਿ ਸਜਨ ਸੋ ਰਤਿ ਕਰਤ ਰੀਝ ਰਹੀ ਮਨ ਮਾਹਿ।","roman":"Kuari sajan so rati karat reejh rahee man maahi |","meaning_en":"The princess made love with her beloved and was delighted in her mind;","page":2079,"meaning_status":"draft"},{"gurmukhi":"ਵਹਿ ਦਿਨ ਪੂਜਾ ਰੁਦ੍ਰ ਕੀ ਭੂਲਿ ਕਰੀ ਤਿਨ ਨਾਹਿ। ੭੬।","roman":"Vahi din poojaa rudr kee bhooli karee tin naahi | 76 |","meaning_en":"that day she did not, even by mistake, do the worship of Rudra.","page":2079,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2079,"meaning_status":"draft"},{"type":"verse","number":[77],"number_text":"੭੭।","page":2079,"lines":[{"gurmukhi":"ਕੁਅਰਿ ਕੁਅਰ ਕੈ ਸੰਗ ਸਿਧਾਈ। ਏਕ ਬਿਵਤ ਮਨ ਮਾਹਿ ਪਕਾਈ।","roman":"Kuari kuar kai sang sidhaaee | ek bivat man maahi pakaaee |","meaning_en":"The princess went with the prince; one plan she held firm in her mind.","page":2079,"meaning_status":"draft"},{"gurmukhi":"ਇਕ ਦੁਰਬਲ ਤ੍ਰਿਯ ਨਿਕਟ ਬਲਾਇਸਿ। ਕਾਨ ਲਾਗਿ ਤਿਹ ਮੰਤ੍ਰ ਸਿਖਾਇਸਿ। ੭੭।","roman":"Ik durbal triy nikat balaaisi | kaan laagi tih mantr sikhaaisi | 77 |","meaning_en":"She called a weak woman near and whispered a mantra in her ear.","page":2079,"meaning_status":"draft"}]},{"type":"verse","number":[78],"number_text":"੭੮।","page":2079,"lines":[{"gurmukhi":"ਅਪਨੀ ਠੌਰ ਤਾਹਿ ਬੈਠਾਯੋ। ਤਾਹਿ ਭਲੀ ਬਿਧਿ ਚਰਿਤ ਸਿਖਾਯੋ।","roman":"Apnee thaur taahi baithaayo | taahi bhalee bidhi charit sikhaayo |","meaning_en":"She seated her in her own place and taught her the trick well.","page":2079,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਸਖਿਯਨ ਜਬ ਤਾਹਿ ਨਿਹਾਰਾ। ਤਿਨ ਤ੍ਰਿਯ ਤਬ ਇਹ ਭਾਤਿ ਉਚਾਰਾ। ੭੮।","roman":"Sabh sakhiyan jab taahi nihaaraa | tin triy tab ih bhaati uchaaraa | 78 |","meaning_en":"When all the friends saw her, the woman then said this:","page":2079,"meaning_status":"draft"}]},{"type":"verse","number":[79],"number_text":"੭੯।","page":2079,"lines":[{"gurmukhi":"ਮੈ ਸਿਵ ਪੂਜਨ ਕਾਲਿ ਨ ਗਈ। ਤਾ ਤੇ ਸ੍ਰਾਪ ਰੁਦ੍ਰ ਮੁਹਿ ਦਈ।","roman":"Mai siv poojan kaali na gaee | taa te sraap rudr muhi daee |","meaning_en":"\"I did not go to worship Shiva yesterday, so Rudra cursed me.","page":2079,"meaning_status":"draft"},{"gurmukhi":"ਯਾ ਤੇ ਅਵਰ ਬਰਨ ਹ੍ਵੈ ਗਯੋ। ਗੋਰ ਬਰਨ ਤੇ ਸਾਂਵਰ ਭਯੋ। ੭੯।","roman":"Yaa te avar baran hvai gayo | gor baran te saanvar bhayo | 79 |","meaning_en":"Because of this my colour has changed: from fair I have become dark.\"","page":2079,"meaning_status":"draft"}]},{"type":"verse","number":[80],"number_text":"੮੦।","page":2079,"lines":[{"gurmukhi":"ਸਭ ਸਖਿਯਨ ਇਹ ਭਾਤਿ ਸੁਨਾ ਜਬ। ਮਿਲਿ ਰਾਜਾ ਪਹਿ ਜਾਤ ਭਈ ਸਬ।","roman":"Sabh sakhiyan ih bhaati sunaa jab | mili raajaa pahi jaat bhaee sab |","meaning_en":"When all the friends heard this, they all went together to the king,","page":2079,"meaning_status":"draft"},{"gurmukhi":"ਸਭ ਬ੍ਰਿਤਾਤ ਕਹਿ ਤਾਹਿ ਸੁਨਾਯੋ। ਦੁਹਿਤਹਿ ਤਾਤ ਬਿਲੋਕਨ ਆਯੋ। ੮੦।","roman":"Sabh britaat kahi taahi sunaayo | duhithi taat bilokan aayo | 80 |","meaning_en":"told him the whole account, and the father came to see his daughter.","page":2079,"meaning_status":"draft"}]},{"type":"verse","number":[81],"number_text":"੮੧।","page":2079,"lines":[{"gurmukhi":"ਅਨਤ ਬਰਨ ਰਾਜੈ ਜਬ ਲਹਾ। ਇਹ ਬਿਧਿ ਸੋ ਰਾਨੀ ਤਨ ਕਹਾ।","roman":"Anat baran raajai jab lahaa | ih bidhi so raanee tan kahaa |","meaning_en":"When the king saw her colour changed, he said to the queen in this way,","page":2079,"meaning_status":"draft","note":"ਰਾਨੀ ਤਨ ਕਹਾ: 'said to the queen'; the sense may be 'said to the woman (the substitute)'; printed so."},{"gurmukhi":"ਕਹਾ ਭਯੋ ਇਹ ਰਾਜ ਦੁਲਾਰੀ। ਗੋਰੀ ਹੁਤੀ ਹ੍ਵੈ ਗਈ ਕਾਰੀ। ੮੧।","roman":"Kahaa bhayo ih raaj dulaaree | goree hutee hvai gaee kaaree | 81 |","meaning_en":"\"What has happened, king's darling? You were fair and have become dark.\"","page":2079,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":2079,"meaning_status":"draft"},{"type":"verse","number":[82],"number_text":"੮੨।","page":2079,"lines":[{"gurmukhi":"ਬਿਰਧ ਤਰੁਨਿ ਤੇ ਹ੍ਵੈ ਗਈ ਭਈ ਗੋਰਿ ਤੇ ਸ੍ਯਾਮ।","roman":"Biradh taruni te hvai gaee bhaee gori te syaam |","meaning_en":"\"I had been old and became young; I had been fair and became dark;","page":2079,"meaning_status":"draft","note":"Read as the substitute's answer; printed lines are obscure; uncertain."},{"gurmukhi":"ਸਤਿ ਸ੍ਰਾਪ ਸਿਵ ਐਸਈ ਜਪੋ ਸਕਲ ਸਭ ਜਾਮ। ੮੨।","roman":"Sati sraap siv aisaee japo sakal sabh jaam | 82 |","meaning_en":"it is Shiva's true curse; so do I always chant, at every watch.\"","page":2079,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":2079,"meaning_status":"draft"},{"type":"verse","number":[83],"number_text":"੮੩।","page":2079,"lines":[{"gurmukhi":"ਮੂਰਖ ਰਾਜ ਬਾਤ ਨਹਿ ਜਾਨੀ। ਔਰ ਨਾਰਿ ਦੁਹਿਤਾ ਪਹਿਚਾਨੀ।","roman":"Moorakh raaj baat nahi jaanee | aur naari duhitaa pahichaanee |","meaning_en":"The foolish king did not understand the matter; he took her for another woman, his daughter.","page":2079,"meaning_status":"draft","note":"Printed so; read as the king taking the substitute for his daughter."},{"gurmukhi":"ਬਿਰਹ ਮਤੀ ਮਿਤਵਾ ਸੰਗ ਗਈ। ਬਹੁ ਬਿਧਿ ਭੋਗ ਕਮਾਵਤ ਭਈ। ੮੩।","roman":"Birah matee mitvaa sang gaee | bahu bidhi bhog kamaavat bhaee | 83 |","meaning_en":"Birah Mati went with her beloved and enjoyed pleasures in many ways.","page":2079,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":2081,"meaning_status":"draft"},{"type":"verse","number":[84,1],"number_text":"੮੪। ੧।","page":2081,"lines":[{"gurmukhi":"ਇਕ ਦਿਨ ਧਾਮ ਪਰੀ ਕੇ ਦੇਤ ਪਠਾਇ ਕੈ।","roman":"Ik din dhaam paree ke det pathaai kai |","meaning_en":"One day she would send him to the fairy's house,","page":2081,"meaning_status":"draft"},{"gurmukhi":"ਇਕ ਦਿਨ ਆਪੁ ਕਲੋਲ ਕਰਤ ਸੁਖ ਪਾਇ ਕੈ।","roman":"Ik din aapu kalol karat sukh paai kai |","meaning_en":"and one day she herself would take pleasure and make love,","page":2081,"meaning_status":"draft"},{"gurmukhi":"ਅਰਧਾਰਧ ਬਜਾਵੈ ਤਾ ਸੌ ਰੈਨਿ ਦਿਨ।","roman":"Ardhaaradh bajaavai taa sau raini din |","meaning_en":"sharing him half and half, night and day;","page":2081,"meaning_status":"draft","note":"ਅਰਧਾਰਧ: 'in half and half portions'; read so."},{"gurmukhi":"ਹੋ ਮੂਰਖ ਬਾਤ ਨ ਪਾਈ ਰਾਜੈ ਕਛੂ ਇਨ। ੮੪। ੧।","roman":"Ho moorakh baat na paaee raajai kachhoo in | 84 | 1 |","meaning_en":"the foolish king found out nothing of this.","page":2081,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਚਰਿਤ੍ਰ ਪਖ੍ਯਾਨੇ ਤ੍ਰਿਯਾ ਚਰਿਤ੍ਰੇ ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਬਾਦੇ ਦੋਇ ਸੌ ਚੌਸਠਿ ਚਰਿਤ੍ਰ ਸਮਾਪਤਮ","roman":"Iti sree charitr pakhyaane triyaa charitre mantree bhoop sanbaade doi sau chausthi charitr samaaptam","meaning_en":"Thus ends the 264th charitra of the Charitropakhyan, of the wiles of women, in the dialogue of the minister and the king; complete.","page":2081,"meaning_status":"draft"},{"gurmukhi":"ਸਤੁ ਸੁਭਮ ਸਤੁ। ੨੬੪। ੫੦੫੨। ਅਫਜੂੰ।","roman":"Satu subham satu | 264 | 5052 | aphjoon |","meaning_en":"True, auspicious, true. 264. 5052. It continues.","page":2081,"meaning_status":"draft"}],"page":2081,"number":[264,5052]}});
